<?php
namespace Azuriom\Plugin\GamingHubCore\Services; use Azuriom\Plugin\GamingHubCore\Data\ExtensionManifest; use Azuriom\Plugin\GamingHubCore\Exceptions\ExtensionCompatibilityFailed;
final class ExtensionCompatibility { public function assertCompatible(ExtensionManifest $m,string $coreVersion,string $azuriomVersion,string $phpVersion):void {foreach(['gaming-hub-core'=>$coreVersion,'azuriom'=>$azuriomVersion,'php'=>$phpVersion] as $key=>$version){$constraint=$m->requires[$key];if(class_exists(\Composer\Semver\Semver::class)){if(!\Composer\Semver\Semver::satisfies($version,$constraint))throw new ExtensionCompatibilityFailed($key.' '.$constraint.' is required.');}elseif(!$this->basic($version,$constraint))throw new ExtensionCompatibilityFailed('Composer Semver is unavailable and the simple constraint was not satisfied: '.$key);}foreach(($m->requires['extensions']??[]) as $id=>$constraint){if(!is_string($id)||!is_string($constraint))throw new ExtensionCompatibilityFailed('Invalid extension dependency.');}}
 private function basic(string $v,string $c):bool {if(preg_match('/^>=?\s*(\d+\.\d+\.\d+)$/',$c,$m))return version_compare($v,$m[1],'>=');if(preg_match('/^\^?(\d+\.\d+\.\d+)$/',$c,$m))return version_compare($v,$m[1],'>=')&&version_compare($v,((int)explode('.',$m[1])[0]+1).'.0.0','<');return false;}
}
